insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest landing at MSP asks where to meet the hotel shuttle. Where do you send them?','Un huésped que acaba de aterrizar en MSP pregunta dónde lo recoge el shuttle del hotel. ¿A dónde lo mandas?','["The upper departures curb", "The light rail platform", "Level 1 of the Gold Ramp", "Baggage claim carousel 1"]'::jsonb,'["A la acera de salidas, en el nivel superior", "Al andén del tren ligero", "Al nivel 1 del Gold Ramp", "Al carrusel de equipaje 1"]'::jsonb,2,'MSP''s hotel shuttles pick up on Level 1 of the Gold Ramp. Ask the guest to call 952-854-7600 once they have their bags.','Los shuttles de hotel en MSP recogen en el nivel 1 del Gold Ramp. Pídele al huésped que llame al 952-854-7600 cuando ya tenga sus maletas.','https://www.mspairport.com/directions/ground-transportation/hotel-shuttles',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest says they''re flying Sun Country tomorrow. Which terminal do you drop them at?','Un huésped dice que mañana vuela con Sun Country. ¿En qué terminal lo dejas?','["The Gold Ramp", "Terminal 2", "Terminal 1", "Either one, they''re connected landside"]'::jsonb,'["En el Gold Ramp", "En la Terminal 2", "En la Terminal 1", "En cualquiera, están conectadas por fuera"]'::jsonb,1,'Sun Country flies out of Terminal 2 (Humphrey). The two terminals are on separate roads, so always confirm the airline first.','Sun Country sale de la Terminal 2 (Humphrey). Las terminales están en caminos distintos, así que siempre confirma la aerolínea primero.','https://www.mspairport.com/airport/terminal-information',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest flying Delta asks which terminal to go to.','Un huésped que vuela con Delta pregunta a qué terminal debe ir.','["Terminal 1", "Delta uses both equally", "Terminal 2", "The terminal closest to the hotel"]'::jsonb,'["A la Terminal 1", "Delta usa las dos por igual", "A la Terminal 2", "A la terminal más cercana al hotel"]'::jsonb,0,'Delta operates from Terminal 1 (Lindbergh), concourses A–G.','Delta opera desde la Terminal 1 (Lindbergh), en los concourses A a G.','https://www.mspairport.com/flights-and-airlines',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest on Southwest asks which terminal is theirs.','Un huésped que vuela con Southwest pregunta cuál es su terminal.','["Either terminal works", "Terminal 2", "Southwest flies from St. Paul Downtown Airport", "Terminal 1"]'::jsonb,'["Cualquiera de las dos", "La Terminal 2", "Southwest sale del aeropuerto del centro de St. Paul", "La Terminal 1"]'::jsonb,1,'Southwest, Sun Country, Frontier and Icelandair use Terminal 2.','Southwest, Sun Country, Frontier e Icelandair usan la Terminal 2.','https://www.mspairport.com/airport/terminal-information',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest flying United asks which terminal.','Un huésped que vuela con United pregunta qué terminal le toca.','["United only uses Terminal 2 on weekends", "Terminal 1", "Terminal 2", "Terminal 3"]'::jsonb,'["United solo usa la Terminal 2 los fines de semana", "La Terminal 1", "La Terminal 2", "La Terminal 3"]'::jsonb,1,'United (along with American, Alaska, Air Canada and Delta) is at Terminal 1.','United (igual que American, Alaska, Air Canada y Delta) está en la Terminal 1.','https://www.mspairport.com/airport/terminal-information',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest was dropped at the wrong terminal and has 90 minutes. What''s the fastest free way between terminals?','Dejaron a un huésped en la terminal equivocada y tiene 90 minutos. ¿Cuál es la forma gratis más rápida de cambiarse?','["A taxi between terminals", "Walk the skyway between terminals", "The Blue Line light rail between Terminal 1 and Terminal 2 — no fare", "Wait for the next hotel shuttle loop"]'::jsonb,'["Un taxi entre terminales", "Caminar por el skyway de una a otra", "El tren ligero Blue Line entre la Terminal 1 y la 2, sin costo", "Esperar la siguiente vuelta del shuttle del hotel"]'::jsonb,2,'The Blue Line runs between the two terminal stations 24 hours a day and that ride is free.','La Blue Line corre entre las dos estaciones de terminal las 24 horas, y ese tramo es gratis.','https://www.metrotransit.org/blue-line-station-maps',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','A guest wants to take light rail to a Twins game. Which station do they get off at?','Un huésped quiere ir en tren ligero a un partido de los Twins. ¿En qué estación se baja?','["Target Field", "Nicollet Mall", "Mall of America", "U.S. Bank Stadium"]'::jsonb,'["Target Field", "Nicollet Mall", "Mall of America", "U.S. Bank Stadium"]'::jsonb,0,'The Twins play at Target Field, and the Blue Line ends at Target Field Station.','Los Twins juegan en Target Field, y la Blue Line termina en la estación Target Field.','https://www.metrotransit.org/stadiums/target-field/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','A guest wants to go to a Vikings game by train. Which Blue Line stop?','Un huésped quiere ir en tren a un partido de los Vikings. ¿En qué parada de la Blue Line se baja?','["U.S. Bank Stadium", "Franklin Avenue", "Target Field", "Fort Snelling"]'::jsonb,'["U.S. Bank Stadium", "Franklin Avenue", "Target Field", "Fort Snelling"]'::jsonb,0,'The Vikings play at U.S. Bank Stadium, which has its own Blue Line station.','Los Vikings juegan en U.S. Bank Stadium, que tiene su propia estación en la Blue Line.','https://www.minneapolis.org/map-transportation/major-event-parking-transit/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','A guest has Timberwolves tickets. Which light rail stop is closest to Target Center?','Un huésped tiene boletos para los Timberwolves. ¿Qué parada del tren ligero queda más cerca de Target Center?','["Cedar-Riverside", "U.S. Bank Stadium", "Lake Street/Midtown", "Warehouse District/Hennepin Avenue"]'::jsonb,'["Cedar-Riverside", "U.S. Bank Stadium", "Lake Street/Midtown", "Warehouse District/Hennepin Avenue"]'::jsonb,3,'Target Center is next to Warehouse District/Hennepin Ave station on the Blue and Green Lines.','Target Center está junto a la estación Warehouse District/Hennepin Ave, de las líneas Blue y Green.','https://www.minneapolis.org/map-transportation/major-event-parking-transit/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','A guest wants to see the Wild. Where is their arena now?','Un huésped quiere ver a los Wild. ¿Dónde está su arena ahora?','["Inside Mall of America", "Target Center in Minneapolis", "U.S. Bank Stadium", "Grand Casino Arena (formerly Xcel Energy Center) in downtown St. Paul"]'::jsonb,'["Dentro del Mall of America", "En Target Center, en Minneapolis", "En U.S. Bank Stadium", "En el Grand Casino Arena (antes Xcel Energy Center), en el centro de St. Paul"]'::jsonb,3,'The Wild''s arena in St. Paul was renamed Grand Casino Arena. By transit, take the Green Line toward St. Paul.','La arena de los Wild en St. Paul ahora se llama Grand Casino Arena. En transporte público, se toma la Green Line hacia St. Paul.','https://en.wikipedia.org/wiki/Grand_Casino_Arena',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','Which Blue Line station is closest to the hotel?','¿Cuál es la estación de la Blue Line más cercana al hotel?','["American Boulevard", "Fort Snelling", "Target Field", "Lake Street/Midtown"]'::jsonb,'["American Boulevard", "Fort Snelling", "Target Field", "Lake Street/Midtown"]'::jsonb,0,'American Boulevard station (at 34th Ave) is the nearest stop to Metro Drive.','La estación American Boulevard (en la 34th Ave) es la parada más cercana a Metro Drive.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','Heading south from the airport, which Blue Line stop comes right after Terminal 2?','Yendo hacia el sur desde el aeropuerto, ¿qué parada de la Blue Line sigue después de la Terminal 2?','["American Boulevard", "Mall of America", "Fort Snelling", "Bloomington Central"]'::jsonb,'["American Boulevard", "Mall of America", "Fort Snelling", "Bloomington Central"]'::jsonb,0,'Southbound order: Terminal 1, Terminal 2, American Boulevard, Bloomington Central, 30th Avenue, Mall of America.','Orden hacia el sur: Terminal 1, Terminal 2, American Boulevard, Bloomington Central, 30th Avenue, Mall of America.','https://www.metrotransit.org/Schedules/RouteMaps/jun26/blue',array['front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','Which Blue Line station is the end of the line in Bloomington?','¿Cuál es la última estación de la Blue Line en Bloomington?','["Terminal 2", "American Boulevard", "Mall of America", "30th Avenue"]'::jsonb,'["Terminal 2", "American Boulevard", "Mall of America", "30th Avenue"]'::jsonb,2,'Mall of America is the southern end of the Blue Line; Target Field is the northern end.','Mall of America es el extremo sur de la Blue Line; Target Field es el extremo norte.','https://www.metrotransit.org/Schedules/RouteMaps/jun26/blue',array['front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','A guest wants to drive to a Park & Ride and take the train to MOA. Where can they park?','Un huésped quiere manejar a un Park & Ride y tomar el tren al MOA. ¿Dónde puede estacionarse?','["On the street at American Boulevard", "At Terminal 2 for free", "At the Mall of America station Park & Ride", "The 30th Avenue station ramp — MOA station has no Park & Ride"]'::jsonb,'["En la calle junto a American Boulevard", "En la Terminal 2, gratis", "En el Park & Ride de la estación Mall of America", "En la rampa de la estación 30th Avenue; la estación del MOA no tiene Park & Ride"]'::jsonb,3,'Metro Transit says there''s no Park & Ride at Mall of America station and points riders to the 30th/28th Avenue ramp or Fort Snelling.','Metro Transit indica que la estación del Mall of America no tiene Park & Ride y recomienda la rampa de 30th/28th Avenue o Fort Snelling.','https://www.metrotransit.org/blue-line-station-maps',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','A guest wants to go downtown Minneapolis without a car. What''s the simplest option?','Un huésped quiere ir al centro de Minneapolis sin carro. ¿Cuál es la opción más sencilla?','["Blue Line light rail north from American Boulevard", "Route 54 bus to St. Paul", "The hotel shuttle to downtown", "The Red Line to Apple Valley"]'::jsonb,'["La Blue Line hacia el norte desde American Boulevard", "El autobús 54 a St. Paul", "El shuttle del hotel al centro", "La Red Line a Apple Valley"]'::jsonb,0,'The Blue Line goes straight to downtown Minneapolis (Nicollet Mall, Warehouse District, Target Field).','La Blue Line va directo al centro de Minneapolis (Nicollet Mall, Warehouse District, Target Field).','https://www.metrotransit.org/Schedules/RouteMaps/jun26/blue',array['front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','moa','A family asks what time Mall of America opens on a Saturday.','Una familia pregunta a qué hora abre el Mall of America un sábado.','["9 a.m.", "Noon", "8 a.m.", "10 a.m."]'::jsonb,'["A las 9 a. m.", "Al mediodía", "A las 8 a. m.", "A las 10 a. m."]'::jsonb,3,'MOA''s regular hours are Mon–Sat 10 a.m.–9 p.m. and Sunday 11 a.m.–7 p.m. Individual stores can differ.','El horario normal del MOA es de lunes a sábado de 10 a. m. a 9 p. m., y domingo de 11 a. m. a 7 p. m. Algunas tiendas tienen otro horario.','https://www.mallofamerica.com/plan-your-trip/hours-directions',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','moa','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','moa','A guest asks when Mall of America closes on Sunday.','Un huésped pregunta a qué hora cierra el Mall of America el domingo.','["7 p.m.", "Midnight", "5 p.m.", "9 p.m."]'::jsonb,'["A las 7 p. m.", "A medianoche", "A las 5 p. m.", "A las 9 p. m."]'::jsonb,0,'Sunday hours are 11 a.m.–7 p.m. Restaurants and attractions may stay open later.','El domingo abre de 11 a. m. a 7 p. m. Los restaurantes y atracciones pueden cerrar más tarde.','https://www.mallofamerica.com/plan-your-trip/hours-directions',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','moa','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','moa','A guest wants to plan a Monday-night shopping trip. When does MOA close Monday through Saturday?','Un huésped quiere ir de compras el lunes en la noche. ¿A qué hora cierra el MOA de lunes a sábado?','["10 p.m.", "9 p.m.", "7 p.m.", "11 p.m."]'::jsonb,'["A las 10 p. m.", "A las 9 p. m.", "A las 7 p. m.", "A las 11 p. m."]'::jsonb,1,'Mon–Sat MOA is open 10 a.m.–9 p.m.','De lunes a sábado el MOA abre de 10 a. m. a 9 p. m.','https://www.mallofamerica.com/plan-your-trip/hours-directions',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','moa','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','moa','Kids want to ride Nickelodeon Universe on Sunday. What hours do you give them?','Unos niños quieren subirse a Nickelodeon Universe el domingo. ¿Qué horario les das?','["11 a.m.–7 p.m. (check the site for changes)", "It''s closed Sundays", "Noon–midnight", "8 a.m.–10 p.m."]'::jsonb,'["De 11 a. m. a 7 p. m. (revisa el sitio por cambios)", "Cierra los domingos", "Del mediodía a la medianoche", "De 8 a. m. a 10 p. m."]'::jsonb,0,'Nickelodeon Universe''s listed Sunday hours are 11 a.m.–7 p.m.; Mon–Sat 10 a.m.–9 p.m.','El horario publicado de Nickelodeon Universe el domingo es de 11 a. m. a 7 p. m.; de lunes a sábado, de 10 a. m. a 9 p. m.','https://www.mallofamerica.com/directory/nickelodeon-universe',array['front_desk','gm','night_audit']::text[],'role','med',array['local','moa','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','moa','A guest asks if the SEA LIFE aquarium at MOA lets people in right up to closing time.','Un huésped pregunta si el acuario SEA LIFE del MOA deja entrar hasta la hora de cierre.','["Only with a hotel key card", "Yes, until the minute it closes", "No — last entry is about an hour before it closes", "It''s open 24 hours"]'::jsonb,'["Solo con la tarjeta llave del hotel", "Sí, hasta el minuto en que cierra", "No, la última entrada es como una hora antes del cierre", "Abre las 24 horas"]'::jsonb,2,'SEA LIFE closes one hour after last ticket entry, so arrive well before closing.','SEA LIFE cierra una hora después de la última entrada, así que hay que llegar con tiempo.','https://www.mallofamerica.com/directory/sea-life-minnesota-aquarium',array['front_desk','gm','night_audit']::text[],'role','med',array['local','moa','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','moa','How far is the hotel from Mall of America?','¿Qué tan lejos está el hotel del Mall of America?','["About 10 miles", "It''s attached by skyway", "Less than a mile — a few minutes'' drive", "About 5 miles"]'::jsonb,'["A unas 10 millas", "Está conectado por skyway", "A menos de una milla, unos minutos en carro", "A unas 5 millas"]'::jsonb,2,'Metro Drive is about 0.7 miles from MOA, and the hotel shuttle goes there.','Metro Drive está a unas 0.7 millas del MOA, y el shuttle del hotel va para allá.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','moa','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','About how far is the hotel from MSP airport?','¿Más o menos a qué distancia está el hotel del aeropuerto MSP?','["About 15 miles", "About 3–4 miles", "About 10 miles", "Under half a mile"]'::jsonb,'["A unas 15 millas", "A unas 3 o 4 millas", "A unas 10 millas", "A menos de media milla"]'::jsonb,1,'Hilton and Marriott list the airport at roughly 3–4 miles from Metro Drive.','Hilton y Marriott indican que el aeropuerto está a unas 3 o 4 millas de Metro Drive.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','holiday','A guest wants to shop at MOA on Thanksgiving Day. What do you tell them?','Un huésped quiere ir de compras al MOA el Día de Acción de Gracias. ¿Qué le dices?','["Only the food court is open", "It''s open 24 hours that day", "It opens at 7 a.m.", "MOA is closed on Thanksgiving Day"]'::jsonb,'["Que solo abre el área de comida", "Que ese día abre las 24 horas", "Que abre a las 7 a. m.", "Que el MOA cierra el Día de Acción de Gracias"]'::jsonb,3,'MOA''s holiday page lists it closed on Thanksgiving and Christmas Day.','La página de días festivos del MOA indica que cierra en Acción de Gracias y en Navidad.','https://www.mallofamerica.com/holiday',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','holiday','mspam']::text[],'MSPAM','11-15','11-28','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','holiday','A guest asks about MOA hours on Black Friday.','Un huésped pregunta por el horario del MOA el Black Friday.','["Opens at 7 a.m., closes at 9 p.m.", "Closed", "Opens at noon", "Opens at midnight"]'::jsonb,'["Abre a las 7 a. m. y cierra a las 9 p. m.", "Está cerrado", "Abre al mediodía", "Abre a medianoche"]'::jsonb,0,'MOA lists Black Friday hours of 7 a.m.–9 p.m.','El MOA publica que en Black Friday abre de 7 a. m. a 9 p. m.','https://www.mallofamerica.com/holiday',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','holiday','mspam']::text[],'MSPAM','11-15','11-28','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','holiday','A guest wants to go to MOA on Christmas Eve afternoon. What hours do you give?','Un huésped quiere ir al MOA la tarde de Nochebuena. ¿Qué horario le das?','["Noon–4 p.m.", "Closed all day", "10 a.m.–6 p.m.", "Open until 11 p.m."]'::jsonb,'["Del mediodía a las 4 p. m.", "Cerrado todo el día", "De 10 a. m. a 6 p. m.", "Abierto hasta las 11 p. m."]'::jsonb,2,'Christmas Eve, New Year''s Eve and New Year''s Day are listed as 10 a.m.–6 p.m.; Christmas Day is closed.','Nochebuena, el 31 de diciembre y el 1 de enero el MOA abre de 10 a. m. a 6 p. m.; el día de Navidad cierra.','https://www.mallofamerica.com/holiday',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','holiday','mspam']::text[],'MSPAM','12-10','01-01','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','health','A guest has a bad sore throat and wants to be seen today, near the hotel. What''s a good walk-in option?','Un huésped tiene mucho dolor de garganta y quiere que lo vean hoy cerca del hotel. ¿Qué opción sin cita le recomiendas?','["The airport TSA office", "The hotel''s first aid kit only", "Wait until they get home", "The M Health Fairview walk-in clinic inside Mall of America"]'::jsonb,'["La oficina de la TSA en el aeropuerto", "Solo el botiquín del hotel", "Que espere a llegar a su casa", "La clínica sin cita de M Health Fairview dentro del Mall of America"]'::jsonb,3,'M Health Fairview has a walk-in clinic inside MOA (East Broadway), open seven days. For an emergency, call 911.','M Health Fairview tiene una clínica sin cita dentro del MOA (East Broadway), abierta los siete días. Si es una emergencia, llama al 911.','https://www.mallofamerica.com/directory/MHealthFairview',array['front_desk','gm','night_audit']::text[],'role','med',array['local','health','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','health','A guest needs urgent care in the evening, after the MOA clinic closes. Which nearby option is open until 8 p.m.?','Un huésped necesita atención urgente en la noche, cuando ya cerró la clínica del MOA. ¿Qué opción cercana abre hasta las 8 p. m.?','["The hotel shuttle office", "M Health Fairview Urgent Care – Oxboro (600 W. 98th St.)", "SEA LIFE first aid", "The Walgreens inside MOA"]'::jsonb,'["La oficina del shuttle del hotel", "M Health Fairview Urgent Care – Oxboro (600 W. 98th St.)", "Los primeros auxilios de SEA LIFE", "El Walgreens dentro del MOA"]'::jsonb,1,'Oxboro urgent care in Bloomington is listed as open until 8 p.m. For chest pain, trouble breathing or anything serious, call 911.','La clínica de urgencias Oxboro en Bloomington abre hasta las 8 p. m. Si hay dolor de pecho, dificultad para respirar o algo grave, llama al 911.','https://www.mhealthfairview.org/locations/m-health-fairview-urgent-care---oxboro',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','health','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','health','A guest needs a prescription filled and asks about the Walgreens inside Mall of America. What should you know?','Un huésped necesita surtir una receta y pregunta por el Walgreens dentro del Mall of America. ¿Qué debes saber?','["It''s the only pharmacy in Bloomington", "The MOA Walgreens has no pharmacy — send them to a full pharmacy", "It''s a 24-hour pharmacy", "It fills prescriptions only on Sundays"]'::jsonb,'["Es la única farmacia en Bloomington", "El Walgreens del MOA no tiene farmacia; mándalo a una farmacia completa", "Es una farmacia 24 horas", "Solo surte recetas los domingos"]'::jsonb,1,'MOA''s directory notes its Walgreens is not a pharmacy. Look up a full pharmacy and confirm hours by phone.','El directorio del MOA indica que su Walgreens no tiene farmacia. Busca una farmacia completa y confirma el horario por teléfono.','https://www.mallofamerica.com/directory/Walgreens',array['front_desk','gm','night_audit']::text[],'role','med',array['local','health','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','health','A guest collapses and isn''t breathing normally. What do you do first?','Un huésped se desmaya y no respira bien. ¿Qué haces primero?','["Drive them to urgent care in the shuttle", "Call 911, then follow the dispatcher and alert your manager", "Wait to see if they feel better", "Look up the nearest clinic"]'::jsonb,'["Llevarlo a urgencias en el shuttle", "Llamar al 911, seguir las indicaciones de la operadora y avisar a tu gerente", "Esperar a ver si se siente mejor", "Buscar la clínica más cercana"]'::jsonb,1,'Urgent care is for minor issues. Anything life-threatening is a 911 call — never transport them yourself.','Las clínicas de urgencias son para cosas menores. Algo que pone en riesgo la vida es para el 911; nunca lo lleves tú.','https://www.redcross.org/take-a-class/cpr',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','health','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','food','At 2 a.m., a guest asks where they can sit down and eat nearby. What''s a verified 24-hour option?','A las 2 a. m., un huésped pregunta dónde puede sentarse a comer cerca. ¿Qué opción 24 horas está confirmada?','["The MOA food court", "IHOP on Killebrew Drive", "The hotel breakfast area", "Nine Mile Brewing"]'::jsonb,'["El área de comida del MOA", "El IHOP de Killebrew Drive", "El área de desayuno del hotel", "Nine Mile Brewing"]'::jsonb,1,'IHOP at 2231 Killebrew Dr. lists 24-hour service. Always suggest the guest check the app in case hours change.','El IHOP de 2231 Killebrew Dr. abre las 24 horas. Siempre sugiere revisar la app por si cambian el horario.','https://restaurants.ihop.com/en-us/mn/bloomington/breakfast-2231-killebrew-dr-5437/late-night-food',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','food','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','food','A guest wants a late-night drive-thru burger. Which nearby spot is listed as open 24 hours?','Un huésped quiere una hamburguesa de autoservicio en la madrugada. ¿Qué lugar cercano abre las 24 horas?','["The Walgreens inside MOA", "The MOA food court", "Nine Mile Brewing", "Wendy''s at 2001 W. American Blvd"]'::jsonb,'["El Walgreens dentro del MOA", "El área de comida del MOA", "Nine Mile Brewing", "El Wendy''s de 2001 W. American Blvd"]'::jsonb,3,'That Wendy''s lists 24-hour drive-thru. Hours can change, so suggest checking the app before heading out.','Ese Wendy''s tiene autoservicio 24 horas. El horario puede cambiar, así que sugiere revisar la app antes de salir.','https://locations.wendys.com/united-states/mn/bloomington/2001-american-blvd-w',array['front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','food','A guest wants an all-day-breakfast diner open around the clock. Which one do you suggest?','Un huésped quiere un diner con desayuno todo el día, abierto a cualquier hora. ¿Cuál le sugieres?','["SEA LIFE café", "Target", "Denny''s on W. American Blvd", "The hotel bar"]'::jsonb,'["La cafetería de SEA LIFE", "Target", "El Denny''s de W. American Blvd", "El bar del hotel"]'::jsonb,2,'Denny''s at 4209 W. American Blvd lists 24-hour service with all-day breakfast.','El Denny''s de 4209 W. American Blvd abre las 24 horas y tiene desayuno todo el día.','https://locations.dennys.com/mn/bloomington/248080',array['front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','shopping','A guest forgot a phone charger and asks for the nearest Target.','A un huésped se le olvidó el cargador y pregunta por el Target más cercano.','["There''s no Target in Bloomington", "There''s a Target inside Terminal 1", "Target Knollwood in St. Louis Park", "Target Bloomington 79th and Penn (2555 W. 79th St.)"]'::jsonb,'["No hay Target en Bloomington", "Hay un Target dentro de la Terminal 1", "El Target Knollwood en St. Louis Park", "El Target Bloomington 79th and Penn (2555 W. 79th St.)"]'::jsonb,3,'Target''s store locator lists Bloomington 79th and Penn at 2555 W. 79th St. MOA stores are closer for small items.','El buscador de Target muestra la tienda Bloomington 79th and Penn en 2555 W. 79th St. Para cosas pequeñas, las tiendas del MOA quedan más cerca.','https://www.target.com/sl/bloomington-79th-and-penn/5',array['front_desk','gm','night_audit']::text[],'role','med',array['local','shopping','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','liquor','At 9:30 p.m. on a Tuesday, a guest asks if they can still buy a bottle of wine at a liquor store. What do you say?','A las 9:30 p. m. de un martes, un huésped pregunta si todavía puede comprar una botella de vino en una licorería. ¿Qué le dices?','["Yes, but hurry — Minnesota liquor stores can sell until 10 p.m. Mon–Sat", "Liquor stores can''t sell wine", "Yes, until 2 a.m.", "No, stores close at 8 p.m."]'::jsonb,'["Sí, pero que se apure: en Minnesota las licorerías venden hasta las 10 p. m. de lunes a sábado", "Las licorerías no pueden vender vino", "Sí, hasta las 2 a. m.", "No, cierran a las 8 p. m."]'::jsonb,0,'State law allows off-sale 8 a.m.–10 p.m. Mon–Sat. Individual stores and cities may close earlier.','La ley estatal permite vender para llevar de 8 a. m. a 10 p. m. de lunes a sábado. Cada tienda o ciudad puede cerrar antes.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['front_desk','gm','night_audit']::text[],'role','med',array['local','liquor','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','liquor','A guest asks on Sunday afternoon whether liquor stores are open.','Un huésped pregunta el domingo en la tarde si las licorerías están abiertas.','["Only in St. Paul", "Yes, until 10 p.m.", "No, Sunday sales are banned in Minnesota", "Yes, they can open 11 a.m.–6 p.m. on Sunday"]'::jsonb,'["Solo en St. Paul", "Sí, hasta las 10 p. m.", "No, en Minnesota no se vende los domingos", "Sí, pueden abrir de 11 a. m. a 6 p. m. el domingo"]'::jsonb,3,'Minnesota allows Sunday off-sale 11 a.m.–6 p.m. Stores choose whether to open.','Minnesota permite vender para llevar el domingo de 11 a. m. a 6 p. m. Cada tienda decide si abre.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['front_desk','gm','night_audit']::text[],'role','med',array['local','liquor','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','liquor','On Christmas Eve at 8:30 p.m. a guest wants to buy champagne at a liquor store. What''s the rule?','En Nochebuena a las 8:30 p. m. un huésped quiere comprar champán en una licorería. ¿Cuál es la regla?','["Off-sale ends at 8 p.m. on Christmas Eve, so they''re too late", "Only grocery stores can sell it", "It''s like any other night, until 10 p.m.", "Stores stay open until midnight"]'::jsonb,'["En Nochebuena la venta para llevar termina a las 8 p. m., ya es tarde", "Solo los supermercados pueden venderlo", "Es como cualquier noche, hasta las 10 p. m.", "Las tiendas abren hasta medianoche"]'::jsonb,0,'Minnesota bans off-sale after 8 p.m. on Christmas Eve, and all day on Thanksgiving and Christmas.','En Minnesota no se vende para llevar después de las 8 p. m. en Nochebuena, ni en todo el día de Acción de Gracias o Navidad.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','liquor','mspam']::text[],'MSPAM','12-15','12-26','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','liquor','A guest wants to buy beer at a liquor store on Thanksgiving. What do you tell them?','Un huésped quiere comprar cerveza en una licorería el Día de Acción de Gracias. ¿Qué le dices?','["Open only until noon", "Open normal hours", "Liquor stores can''t sell on Thanksgiving — buy the day before", "Only at the airport"]'::jsonb,'["Abren solo hasta el mediodía", "Abren en horario normal", "Las licorerías no pueden vender en Acción de Gracias; que compre un día antes", "Solo en el aeropuerto"]'::jsonb,2,'State law prohibits off-sale on Thanksgiving Day.','La ley estatal prohíbe la venta para llevar el Día de Acción de Gracias.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['front_desk','gm','night_audit']::text[],'role','med',array['local','liquor','mspam']::text[],'MSPAM','11-15','11-28','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','winter','It snowed overnight and Bloomington declared a snow emergency. A guest parked on the street. What do you tell them?','Nevó en la noche y Bloomington declaró emergencia por nieve. Un huésped se estacionó en la calle. ¿Qué le dices?','["Only trucks need to move", "It''s fine, the ban is only downtown", "Move it into the hotel lot — city streets must be clear until plowed or the car can be towed", "Leave it, plows go around cars"]'::jsonb,'["Solo deben moverse las camionetas", "No pasa nada, la prohibición es solo en el centro", "Que lo mueva al estacionamiento del hotel; las calles deben quedar libres hasta que pase el quitanieves o se lo pueden llevar", "Que lo deje, los quitanieves le dan la vuelta"]'::jsonb,2,'In a Bloomington snow emergency, vehicles must be off city streets until plowed full width (up to 48 hours) or they may be towed.','Durante una emergencia por nieve en Bloomington, los carros deben salir de las calles hasta que se limpien por completo (hasta 48 horas) o los pueden remolcar.','https://www.bloomingtonmn.gov/mnt/snow-removal-and-snow-emergency-information',array['front_desk','gm','night_audit']::text[],'role','med',array['local','winter','mspam']::text[],'MSPAM','11-01','04-15','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','winter','A guest from Texas asks how early to leave for a 7 a.m. flight during a snowstorm. Best advice?','Un huésped de Texas pregunta con cuánto tiempo salir para un vuelo de las 7 a. m. durante una tormenta de nieve. ¿El mejor consejo?','["Leave 15 minutes before boarding", "Wait until the snow stops", "Leave earlier than usual and check the flight status — roads and security can be slow", "Same as a sunny day"]'::jsonb,'["Salir 15 minutos antes de abordar", "Esperar a que deje de nevar", "Salir antes de lo normal y revisar el estado del vuelo; las calles y la seguridad pueden ir lentas", "Igual que un día soleado"]'::jsonb,2,'Snow slows roads, de-icing delays flights and lines build. Add buffer time and confirm with the airline.','La nieve hace más lentas las calles, el deshielo retrasa los vuelos y se hacen filas. Hay que dejar tiempo extra y confirmar con la aerolínea.','https://www.mspairport.com/airport/terminal-information',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','winter','mspam']::text[],'MSPAM','11-01','04-15','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest landed and wants Uber instead of the shuttle at Terminal 1. Where''s pickup?','Un huésped aterrizó en la Terminal 1 y prefiere Uber en vez del shuttle. ¿Dónde lo recogen?','["Any door outside baggage claim", "Follow Ground Transportation signs to the rideshare zone on Level 1 of the Ground Transportation Center", "Upper departures curb", "Gold Ramp Level 1 shuttle stop"]'::jsonb,'["Cualquier puerta afuera del área de equipaje", "Seguir los letreros de Ground Transportation a la zona de rideshare en el nivel 1 del Ground Transportation Center", "La acera de salidas", "La parada de shuttles del Gold Ramp, nivel 1"]'::jsonb,1,'At Terminal 1 rideshare pickups are in the Ground Transportation Center, Level 1 (Zones A–C).','En la Terminal 1 el rideshare recoge en el Ground Transportation Center, nivel 1 (zonas A a C).','https://www.mspairport.com/directions/ground-transportation/app-based-ride-services',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest at Terminal 2 can''t find their Lyft. Where should they go?','Un huésped en la Terminal 2 no encuentra su Lyft. ¿A dónde debe ir?','["The old Purple Ramp curb", "Gold Ramp Level 1", "Skyway level of the Ground Transportation Center", "The departures curb"]'::jsonb,'["A la acera vieja del Purple Ramp", "Al nivel 1 del Gold Ramp", "Al nivel skyway del Ground Transportation Center", "A la acera de salidas"]'::jsonb,2,'Terminal 2 rideshare pickup moved to the skyway level of the Ground Transportation Center. The old location no longer applies.','En la Terminal 2 el rideshare se cambió al nivel skyway del Ground Transportation Center. La ubicación anterior ya no aplica.','https://www.mspairport.com/directions/ground-transportation/app-based-ride-services',array['driver','front_desk','gm','night_audit']::text[],'role','hard',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','shuttle','A guest calls from the airport for the shuttle. What number should they have called?','Un huésped llama desde el aeropuerto pidiendo el shuttle. ¿A qué número debía llamar?','["Metro Transit", "911", "The airport main line", "The hotel''s front desk, 952-854-7600"]'::jsonb,'["A Metro Transit", "Al 911", "A la línea principal del aeropuerto", "A la recepción del hotel, 952-854-7600"]'::jsonb,3,'Guests call the hotel at 952-854-7600 after collecting bags; the shuttle meets them at Gold Ramp Level 1.','El huésped llama al hotel al 952-854-7600 cuando ya tenga sus maletas; el shuttle lo recoge en el Gold Ramp, nivel 1.','https://www.mspairport.com/directions/ground-transportation/hotel-shuttles',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','shuttle','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','shuttle','A guest asks if the shuttle costs anything to MSP or MOA.','Un huésped pregunta si el shuttle al MSP o al MOA cuesta algo.','["Free only for Gold members", "Only the airport is free", "No, it''s complimentary", "$10 each way"]'::jsonb,'["Gratis solo para socios Gold", "Solo el del aeropuerto es gratis", "No, es gratis", "$10 por trayecto"]'::jsonb,2,'Hampton Inn & Suites MSP Airport/Mall of America lists a complimentary shuttle to both the airport and Mall of America.','Hampton Inn & Suites MSP Airport/Mall of America ofrece shuttle gratuito al aeropuerto y al Mall of America.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','shuttle','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','shuttle','A guest wants the shuttle to drop them at a restaurant downtown Minneapolis. What do you say?','Un huésped quiere que el shuttle lo deje en un restaurante del centro de Minneapolis. ¿Qué le dices?','["Explain the shuttle serves MSP and MOA, and offer the Blue Line or a rideshare", "Charge them cash", "Say downtown is unsafe", "Take them since it''s slow"]'::jsonb,'["Explicarle que el shuttle va al MSP y al MOA, y ofrecerle la Blue Line o un rideshare", "Cobrarle en efectivo", "Decirle que el centro es peligroso", "Llevarlo porque está tranquilo"]'::jsonb,0,'The hotel lists shuttle service to the airport and MOA. Offer friendly alternatives instead of going off-route.','El hotel ofrece shuttle al aeropuerto y al MOA. Ofrece alternativas amables en vez de salirte de la ruta.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','shuttle','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','parking','A guest asks about parking at the hotel.','Un huésped pregunta por el estacionamiento del hotel.','["Send them to the MOA ramp", "Say there''s no parking", "Tell them it''s always free", "Give the current posted rate and in/out rules from the desk — rates change"]'::jsonb,'["Mandarlo a la rampa del MOA", "Decirle que no hay estacionamiento", "Decirle que siempre es gratis", "Darle la tarifa vigente y las reglas de entrada y salida que tiene la recepción; las tarifas cambian"]'::jsonb,3,'Parking rates are set by the hotel and change. Quote what''s posted in the system today.','Las tarifas de estacionamiento las fija el hotel y cambian. Da la que aparece hoy en el sistema.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','parking','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','local','A guest asks what''s the address of the hotel for their Uber.','Un huésped pregunta la dirección del hotel para su Uber.','["6051 Golden Hills Drive", "2860 Metro Drive, Bloomington, MN 55425", "60 E. Broadway, Bloomington", "4300 Glumack Drive"]'::jsonb,'["6051 Golden Hills Drive", "2860 Metro Drive, Bloomington, MN 55425", "60 E. Broadway, Bloomington", "4300 Glumack Drive"]'::jsonb,1,'Know your address cold — guests, drivers and 911 all need it.','Apréndete la dirección de memoria: los huéspedes, los choferes y el 911 la necesitan.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','local','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','local','A guest''s rideshare driver is confused because there are two hotels side by side on Metro Drive. What do you tell the guest?','El chofer de rideshare de un huésped está confundido porque hay dos hoteles juntos en Metro Drive. ¿Qué le dices al huésped?','["Give the exact number 2860 Metro Drive and the hotel name", "Tell them to meet at MOA", "Just say Metro Drive", "Say any door is fine"]'::jsonb,'["Darle el número exacto, 2860 Metro Drive, y el nombre del hotel", "Decirle que se vean en el MOA", "Solo decir Metro Drive", "Decir que cualquier puerta sirve"]'::jsonb,0,'Hampton (2860) and SpringHill (2870) are neighbors on Metro Drive. The exact number avoids mix-ups.','El Hampton (2860) y el SpringHill (2870) están juntos en Metro Drive. El número exacto evita confusiones.','https://www.mspairport.com/directions/ground-transportation/hotel-shuttles',array['front_desk','gm','night_audit']::text[],'role','med',array['local','local','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','local','A guest asks where the Minnesota Zoo is relative to the hotel.','Un huésped pregunta dónde queda el Minnesota Zoo en relación al hotel.','["Next to Target Field", "Across the street", "About 7 miles away, in Apple Valley — best by car or rideshare", "Inside Mall of America"]'::jsonb,'["Junto a Target Field", "Cruzando la calle", "A unas 7 millas, en Apple Valley; mejor en carro o rideshare", "Dentro del Mall of America"]'::jsonb,2,'Hilton lists the Minnesota Zoo at about 7 miles.','Hilton indica que el Minnesota Zoo está a unas 7 millas.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','local','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','transit','Between 11 p.m. and 4:30 a.m., how do travelers get between MSP terminals?','Entre las 11 p. m. y las 4:30 a. m., ¿cómo se mueven los viajeros entre las terminales del MSP?','["Trains still run between the terminals overnight (with a Blue Line airport shuttle option late at night)", "Only taxis", "There''s no way until morning", "Walk outside along the highway"]'::jsonb,'["Los trenes siguen entre terminales en la madrugada (y hay un shuttle de la Blue Line en ciertas horas)", "Solo en taxi", "No hay forma hasta la mañana", "Caminar por la orilla de la carretera"]'::jsonb,0,'Terminal-to-terminal service runs 24 hours; MSP notes a Blue Line airport shuttle option 11 p.m.–4:30 a.m.','El servicio entre terminales funciona las 24 horas; el MSP menciona un shuttle de la Blue Line de 11 p. m. a 4:30 a. m.','https://www.mspairport.com/flights-and-airlines',array['front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','airport','A guest wants to return a rental car at MSP. Which terminal?','Un huésped quiere devolver un carro rentado en el MSP. ¿En qué terminal?','["Either — on-airport rental companies have counters at both", "Only Terminal 1", "At the Mall of America", "Only Terminal 2"]'::jsonb,'["En cualquiera; las rentadoras del aeropuerto tienen mostrador en las dos", "Solo en la Terminal 1", "En el Mall of America", "Solo en la Terminal 2"]'::jsonb,0,'MSP says rental cars can be returned at either terminal.','El MSP indica que los carros rentados se pueden devolver en cualquier terminal.','https://www.mspairport.com/directions/ground-transportation/car-rentals',array['front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest landing at MSP asks where to meet the hotel shuttle. Where do you send them?','Un huésped que acaba de aterrizar en MSP pregunta dónde lo recoge el shuttle del hotel. ¿A dónde lo mandas?','["The light rail platform", "Baggage claim carousel 1", "Level 1 of the Gold Ramp", "The upper departures curb"]'::jsonb,'["Al andén del tren ligero", "Al carrusel de equipaje 1", "Al nivel 1 del Gold Ramp", "A la acera de salidas, en el nivel superior"]'::jsonb,2,'MSP''s hotel shuttles pick up on Level 1 of the Gold Ramp. Ask the guest to call 952-854-0300 once they have their bags.','Los shuttles de hotel en MSP recogen en el nivel 1 del Gold Ramp. Pídele al huésped que llame al 952-854-0300 cuando ya tenga sus maletas.','https://www.mspairport.com/directions/ground-transportation/hotel-shuttles',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest says they''re flying Sun Country tomorrow. Which terminal do you drop them at?','Un huésped dice que mañana vuela con Sun Country. ¿En qué terminal lo dejas?','["Terminal 2", "The Gold Ramp", "Either one, they''re connected landside", "Terminal 1"]'::jsonb,'["En la Terminal 2", "En el Gold Ramp", "En cualquiera, están conectadas por fuera", "En la Terminal 1"]'::jsonb,0,'Sun Country flies out of Terminal 2 (Humphrey). The two terminals are on separate roads, so always confirm the airline first.','Sun Country sale de la Terminal 2 (Humphrey). Las terminales están en caminos distintos, así que siempre confirma la aerolínea primero.','https://www.mspairport.com/airport/terminal-information',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest flying Delta asks which terminal to go to.','Un huésped que vuela con Delta pregunta a qué terminal debe ir.','["Delta uses both equally", "Terminal 1", "The terminal closest to the hotel", "Terminal 2"]'::jsonb,'["Delta usa las dos por igual", "A la Terminal 1", "A la terminal más cercana al hotel", "A la Terminal 2"]'::jsonb,1,'Delta operates from Terminal 1 (Lindbergh), concourses A–G.','Delta opera desde la Terminal 1 (Lindbergh), en los concourses A a G.','https://www.mspairport.com/flights-and-airlines',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest on Southwest asks which terminal is theirs.','Un huésped que vuela con Southwest pregunta cuál es su terminal.','["Either terminal works", "Terminal 2", "Southwest flies from St. Paul Downtown Airport", "Terminal 1"]'::jsonb,'["Cualquiera de las dos", "La Terminal 2", "Southwest sale del aeropuerto del centro de St. Paul", "La Terminal 1"]'::jsonb,1,'Southwest, Sun Country, Frontier and Icelandair use Terminal 2.','Southwest, Sun Country, Frontier e Icelandair usan la Terminal 2.','https://www.mspairport.com/airport/terminal-information',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest flying United asks which terminal.','Un huésped que vuela con United pregunta qué terminal le toca.','["United only uses Terminal 2 on weekends", "Terminal 3", "Terminal 1", "Terminal 2"]'::jsonb,'["United solo usa la Terminal 2 los fines de semana", "La Terminal 3", "La Terminal 1", "La Terminal 2"]'::jsonb,2,'United (along with American, Alaska, Air Canada and Delta) is at Terminal 1.','United (igual que American, Alaska, Air Canada y Delta) está en la Terminal 1.','https://www.mspairport.com/airport/terminal-information',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest was dropped at the wrong terminal and has 90 minutes. What''s the fastest free way between terminals?','Dejaron a un huésped en la terminal equivocada y tiene 90 minutos. ¿Cuál es la forma gratis más rápida de cambiarse?','["A taxi between terminals", "Walk the skyway between terminals", "The Blue Line light rail between Terminal 1 and Terminal 2 — no fare", "Wait for the next hotel shuttle loop"]'::jsonb,'["Un taxi entre terminales", "Caminar por el skyway de una a otra", "El tren ligero Blue Line entre la Terminal 1 y la 2, sin costo", "Esperar la siguiente vuelta del shuttle del hotel"]'::jsonb,2,'The Blue Line runs between the two terminal stations 24 hours a day and that ride is free.','La Blue Line corre entre las dos estaciones de terminal las 24 horas, y ese tramo es gratis.','https://www.metrotransit.org/blue-line-station-maps',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','A guest wants to take light rail to a Twins game. Which station do they get off at?','Un huésped quiere ir en tren ligero a un partido de los Twins. ¿En qué estación se baja?','["Target Field", "Nicollet Mall", "Mall of America", "U.S. Bank Stadium"]'::jsonb,'["Target Field", "Nicollet Mall", "Mall of America", "U.S. Bank Stadium"]'::jsonb,0,'The Twins play at Target Field, and the Blue Line ends at Target Field Station.','Los Twins juegan en Target Field, y la Blue Line termina en la estación Target Field.','https://www.metrotransit.org/stadiums/target-field/',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','A guest wants to go to a Vikings game by train. Which Blue Line stop?','Un huésped quiere ir en tren a un partido de los Vikings. ¿En qué parada de la Blue Line se baja?','["U.S. Bank Stadium", "Target Field", "Fort Snelling", "Franklin Avenue"]'::jsonb,'["U.S. Bank Stadium", "Target Field", "Fort Snelling", "Franklin Avenue"]'::jsonb,0,'The Vikings play at U.S. Bank Stadium, which has its own Blue Line station.','Los Vikings juegan en U.S. Bank Stadium, que tiene su propia estación en la Blue Line.','https://www.minneapolis.org/map-transportation/major-event-parking-transit/',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','A guest has Timberwolves tickets. Which light rail stop is closest to Target Center?','Un huésped tiene boletos para los Timberwolves. ¿Qué parada del tren ligero queda más cerca de Target Center?','["U.S. Bank Stadium", "Warehouse District/Hennepin Avenue", "Cedar-Riverside", "Lake Street/Midtown"]'::jsonb,'["U.S. Bank Stadium", "Warehouse District/Hennepin Avenue", "Cedar-Riverside", "Lake Street/Midtown"]'::jsonb,1,'Target Center is next to Warehouse District/Hennepin Ave station on the Blue and Green Lines.','Target Center está junto a la estación Warehouse District/Hennepin Ave, de las líneas Blue y Green.','https://www.minneapolis.org/map-transportation/major-event-parking-transit/',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','A guest wants to see the Wild. Where is their arena now?','Un huésped quiere ver a los Wild. ¿Dónde está su arena ahora?','["Target Center in Minneapolis", "Inside Mall of America", "Grand Casino Arena (formerly Xcel Energy Center) in downtown St. Paul", "U.S. Bank Stadium"]'::jsonb,'["En Target Center, en Minneapolis", "Dentro del Mall of America", "En el Grand Casino Arena (antes Xcel Energy Center), en el centro de St. Paul", "En U.S. Bank Stadium"]'::jsonb,2,'The Wild''s arena in St. Paul was renamed Grand Casino Arena. By transit, take the Green Line toward St. Paul.','La arena de los Wild en St. Paul ahora se llama Grand Casino Arena. En transporte público, se toma la Green Line hacia St. Paul.','https://en.wikipedia.org/wiki/Grand_Casino_Arena',array['bartender','front_desk','gm','night_audit']::text[],'role','hard',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','Which Blue Line station is closest to the hotel?','¿Cuál es la estación de la Blue Line más cercana al hotel?','["American Boulevard", "Target Field", "Fort Snelling", "Lake Street/Midtown"]'::jsonb,'["American Boulevard", "Target Field", "Fort Snelling", "Lake Street/Midtown"]'::jsonb,0,'American Boulevard station (at 34th Ave) is the nearest stop to Metro Drive.','La estación American Boulevard (en la 34th Ave) es la parada más cercana a Metro Drive.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','Heading south from the airport, which Blue Line stop comes right after Terminal 2?','Yendo hacia el sur desde el aeropuerto, ¿qué parada de la Blue Line sigue después de la Terminal 2?','["Fort Snelling", "Mall of America", "Bloomington Central", "American Boulevard"]'::jsonb,'["Fort Snelling", "Mall of America", "Bloomington Central", "American Boulevard"]'::jsonb,3,'Southbound order: Terminal 1, Terminal 2, American Boulevard, Bloomington Central, 30th Avenue, Mall of America.','Orden hacia el sur: Terminal 1, Terminal 2, American Boulevard, Bloomington Central, 30th Avenue, Mall of America.','https://www.metrotransit.org/Schedules/RouteMaps/jun26/blue',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','Which Blue Line station is the end of the line in Bloomington?','¿Cuál es la última estación de la Blue Line en Bloomington?','["Mall of America", "American Boulevard", "Terminal 2", "30th Avenue"]'::jsonb,'["Mall of America", "American Boulevard", "Terminal 2", "30th Avenue"]'::jsonb,0,'Mall of America is the southern end of the Blue Line; Target Field is the northern end.','Mall of America es el extremo sur de la Blue Line; Target Field es el extremo norte.','https://www.metrotransit.org/Schedules/RouteMaps/jun26/blue',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','A guest wants to drive to a Park & Ride and take the train to MOA. Where can they park?','Un huésped quiere manejar a un Park & Ride y tomar el tren al MOA. ¿Dónde puede estacionarse?','["On the street at American Boulevard", "At Terminal 2 for free", "The 30th Avenue station ramp — MOA station has no Park & Ride", "At the Mall of America station Park & Ride"]'::jsonb,'["En la calle junto a American Boulevard", "En la Terminal 2, gratis", "En la rampa de la estación 30th Avenue; la estación del MOA no tiene Park & Ride", "En el Park & Ride de la estación Mall of America"]'::jsonb,2,'Metro Transit says there''s no Park & Ride at Mall of America station and points riders to the 30th/28th Avenue ramp or Fort Snelling.','Metro Transit indica que la estación del Mall of America no tiene Park & Ride y recomienda la rampa de 30th/28th Avenue o Fort Snelling.','https://www.metrotransit.org/blue-line-station-maps',array['bartender','front_desk','gm','night_audit']::text[],'role','hard',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','A guest wants to go downtown Minneapolis without a car. What''s the simplest option?','Un huésped quiere ir al centro de Minneapolis sin carro. ¿Cuál es la opción más sencilla?','["The Red Line to Apple Valley", "The hotel shuttle to downtown", "Route 54 bus to St. Paul", "Blue Line light rail north from American Boulevard"]'::jsonb,'["La Red Line a Apple Valley", "El shuttle del hotel al centro", "El autobús 54 a St. Paul", "La Blue Line hacia el norte desde American Boulevard"]'::jsonb,3,'The Blue Line goes straight to downtown Minneapolis (Nicollet Mall, Warehouse District, Target Field).','La Blue Line va directo al centro de Minneapolis (Nicollet Mall, Warehouse District, Target Field).','https://www.metrotransit.org/Schedules/RouteMaps/jun26/blue',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','moa','A family asks what time Mall of America opens on a Saturday.','Una familia pregunta a qué hora abre el Mall of America un sábado.','["Noon", "9 a.m.", "8 a.m.", "10 a.m."]'::jsonb,'["Al mediodía", "A las 9 a. m.", "A las 8 a. m.", "A las 10 a. m."]'::jsonb,3,'MOA''s regular hours are Mon–Sat 10 a.m.–9 p.m. and Sunday 11 a.m.–7 p.m. Individual stores can differ.','El horario normal del MOA es de lunes a sábado de 10 a. m. a 9 p. m., y domingo de 11 a. m. a 7 p. m. Algunas tiendas tienen otro horario.','https://www.mallofamerica.com/plan-your-trip/hours-directions',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','moa','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','moa','A guest asks when Mall of America closes on Sunday.','Un huésped pregunta a qué hora cierra el Mall of America el domingo.','["9 p.m.", "7 p.m.", "Midnight", "5 p.m."]'::jsonb,'["A las 9 p. m.", "A las 7 p. m.", "A medianoche", "A las 5 p. m."]'::jsonb,1,'Sunday hours are 11 a.m.–7 p.m. Restaurants and attractions may stay open later.','El domingo abre de 11 a. m. a 7 p. m. Los restaurantes y atracciones pueden cerrar más tarde.','https://www.mallofamerica.com/plan-your-trip/hours-directions',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','moa','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','moa','A guest wants to plan a Monday-night shopping trip. When does MOA close Monday through Saturday?','Un huésped quiere ir de compras el lunes en la noche. ¿A qué hora cierra el MOA de lunes a sábado?','["10 p.m.", "7 p.m.", "11 p.m.", "9 p.m."]'::jsonb,'["A las 10 p. m.", "A las 7 p. m.", "A las 11 p. m.", "A las 9 p. m."]'::jsonb,3,'Mon–Sat MOA is open 10 a.m.–9 p.m.','De lunes a sábado el MOA abre de 10 a. m. a 9 p. m.','https://www.mallofamerica.com/plan-your-trip/hours-directions',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','moa','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','moa','Kids want to ride Nickelodeon Universe on Sunday. What hours do you give them?','Unos niños quieren subirse a Nickelodeon Universe el domingo. ¿Qué horario les das?','["It''s closed Sundays", "8 a.m.–10 p.m.", "11 a.m.–7 p.m. (check the site for changes)", "Noon–midnight"]'::jsonb,'["Cierra los domingos", "De 8 a. m. a 10 p. m.", "De 11 a. m. a 7 p. m. (revisa el sitio por cambios)", "Del mediodía a la medianoche"]'::jsonb,2,'Nickelodeon Universe''s listed Sunday hours are 11 a.m.–7 p.m.; Mon–Sat 10 a.m.–9 p.m.','El horario publicado de Nickelodeon Universe el domingo es de 11 a. m. a 7 p. m.; de lunes a sábado, de 10 a. m. a 9 p. m.','https://www.mallofamerica.com/directory/nickelodeon-universe',array['front_desk','gm','night_audit']::text[],'role','med',array['local','moa','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','moa','A guest asks if the SEA LIFE aquarium at MOA lets people in right up to closing time.','Un huésped pregunta si el acuario SEA LIFE del MOA deja entrar hasta la hora de cierre.','["Yes, until the minute it closes", "Only with a hotel key card", "It''s open 24 hours", "No — last entry is about an hour before it closes"]'::jsonb,'["Sí, hasta el minuto en que cierra", "Solo con la tarjeta llave del hotel", "Abre las 24 horas", "No, la última entrada es como una hora antes del cierre"]'::jsonb,3,'SEA LIFE closes one hour after last ticket entry, so arrive well before closing.','SEA LIFE cierra una hora después de la última entrada, así que hay que llegar con tiempo.','https://www.mallofamerica.com/directory/sea-life-minnesota-aquarium',array['front_desk','gm','night_audit']::text[],'role','med',array['local','moa','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','moa','How far is the hotel from Mall of America?','¿Qué tan lejos está el hotel del Mall of America?','["Less than a mile — a few minutes'' drive", "About 5 miles", "About 10 miles", "It''s attached by skyway"]'::jsonb,'["A menos de una milla, unos minutos en carro", "A unas 5 millas", "A unas 10 millas", "Está conectado por skyway"]'::jsonb,0,'Metro Drive is about 0.7 miles from MOA, and the hotel shuttle goes there.','Metro Drive está a unas 0.7 millas del MOA, y el shuttle del hotel va para allá.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','moa','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','About how far is the hotel from MSP airport?','¿Más o menos a qué distancia está el hotel del aeropuerto MSP?','["Under half a mile", "About 3–4 miles", "About 15 miles", "About 10 miles"]'::jsonb,'["A menos de media milla", "A unas 3 o 4 millas", "A unas 15 millas", "A unas 10 millas"]'::jsonb,1,'Hilton and Marriott list the airport at roughly 3–4 miles from Metro Drive.','Hilton y Marriott indican que el aeropuerto está a unas 3 o 4 millas de Metro Drive.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','holiday','A guest wants to shop at MOA on Thanksgiving Day. What do you tell them?','Un huésped quiere ir de compras al MOA el Día de Acción de Gracias. ¿Qué le dices?','["Only the food court is open", "It opens at 7 a.m.", "It''s open 24 hours that day", "MOA is closed on Thanksgiving Day"]'::jsonb,'["Que solo abre el área de comida", "Que abre a las 7 a. m.", "Que ese día abre las 24 horas", "Que el MOA cierra el Día de Acción de Gracias"]'::jsonb,3,'MOA''s holiday page lists it closed on Thanksgiving and Christmas Day.','La página de días festivos del MOA indica que cierra en Acción de Gracias y en Navidad.','https://www.mallofamerica.com/holiday',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','holiday','mspms']::text[],'MSPMS','11-15','11-28','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','holiday','A guest asks about MOA hours on Black Friday.','Un huésped pregunta por el horario del MOA el Black Friday.','["Closed", "Opens at 7 a.m., closes at 9 p.m.", "Opens at noon", "Opens at midnight"]'::jsonb,'["Está cerrado", "Abre a las 7 a. m. y cierra a las 9 p. m.", "Abre al mediodía", "Abre a medianoche"]'::jsonb,1,'MOA lists Black Friday hours of 7 a.m.–9 p.m.','El MOA publica que en Black Friday abre de 7 a. m. a 9 p. m.','https://www.mallofamerica.com/holiday',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','holiday','mspms']::text[],'MSPMS','11-15','11-28','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','holiday','A guest wants to go to MOA on Christmas Eve afternoon. What hours do you give?','Un huésped quiere ir al MOA la tarde de Nochebuena. ¿Qué horario le das?','["Noon–4 p.m.", "Open until 11 p.m.", "10 a.m.–6 p.m.", "Closed all day"]'::jsonb,'["Del mediodía a las 4 p. m.", "Abierto hasta las 11 p. m.", "De 10 a. m. a 6 p. m.", "Cerrado todo el día"]'::jsonb,2,'Christmas Eve, New Year''s Eve and New Year''s Day are listed as 10 a.m.–6 p.m.; Christmas Day is closed.','Nochebuena, el 31 de diciembre y el 1 de enero el MOA abre de 10 a. m. a 6 p. m.; el día de Navidad cierra.','https://www.mallofamerica.com/holiday',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','holiday','mspms']::text[],'MSPMS','12-10','01-01','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','health','A guest has a bad sore throat and wants to be seen today, near the hotel. What''s a good walk-in option?','Un huésped tiene mucho dolor de garganta y quiere que lo vean hoy cerca del hotel. ¿Qué opción sin cita le recomiendas?','["Wait until they get home", "The airport TSA office", "The hotel''s first aid kit only", "The M Health Fairview walk-in clinic inside Mall of America"]'::jsonb,'["Que espere a llegar a su casa", "La oficina de la TSA en el aeropuerto", "Solo el botiquín del hotel", "La clínica sin cita de M Health Fairview dentro del Mall of America"]'::jsonb,3,'M Health Fairview has a walk-in clinic inside MOA (East Broadway), open seven days. For an emergency, call 911.','M Health Fairview tiene una clínica sin cita dentro del MOA (East Broadway), abierta los siete días. Si es una emergencia, llama al 911.','https://www.mallofamerica.com/directory/MHealthFairview',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','health','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','health','A guest needs urgent care in the evening, after the MOA clinic closes. Which nearby option is open until 8 p.m.?','Un huésped necesita atención urgente en la noche, cuando ya cerró la clínica del MOA. ¿Qué opción cercana abre hasta las 8 p. m.?','["The Walgreens inside MOA", "The hotel shuttle office", "SEA LIFE first aid", "M Health Fairview Urgent Care – Oxboro (600 W. 98th St.)"]'::jsonb,'["El Walgreens dentro del MOA", "La oficina del shuttle del hotel", "Los primeros auxilios de SEA LIFE", "M Health Fairview Urgent Care – Oxboro (600 W. 98th St.)"]'::jsonb,3,'Oxboro urgent care in Bloomington is listed as open until 8 p.m. For chest pain, trouble breathing or anything serious, call 911.','La clínica de urgencias Oxboro en Bloomington abre hasta las 8 p. m. Si hay dolor de pecho, dificultad para respirar o algo grave, llama al 911.','https://www.mhealthfairview.org/locations/m-health-fairview-urgent-care---oxboro',array['bartender','front_desk','gm','night_audit']::text[],'role','hard',array['local','health','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','health','A guest needs a prescription filled and asks about the Walgreens inside Mall of America. What should you know?','Un huésped necesita surtir una receta y pregunta por el Walgreens dentro del Mall of America. ¿Qué debes saber?','["It''s the only pharmacy in Bloomington", "It''s a 24-hour pharmacy", "It fills prescriptions only on Sundays", "The MOA Walgreens has no pharmacy — send them to a full pharmacy"]'::jsonb,'["Es la única farmacia en Bloomington", "Es una farmacia 24 horas", "Solo surte recetas los domingos", "El Walgreens del MOA no tiene farmacia; mándalo a una farmacia completa"]'::jsonb,3,'MOA''s directory notes its Walgreens is not a pharmacy. Look up a full pharmacy and confirm hours by phone.','El directorio del MOA indica que su Walgreens no tiene farmacia. Busca una farmacia completa y confirma el horario por teléfono.','https://www.mallofamerica.com/directory/Walgreens',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','health','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','health','A guest collapses and isn''t breathing normally. What do you do first?','Un huésped se desmaya y no respira bien. ¿Qué haces primero?','["Call 911, then follow the dispatcher and alert your manager", "Look up the nearest clinic", "Wait to see if they feel better", "Drive them to urgent care in the shuttle"]'::jsonb,'["Llamar al 911, seguir las indicaciones de la operadora y avisar a tu gerente", "Buscar la clínica más cercana", "Esperar a ver si se siente mejor", "Llevarlo a urgencias en el shuttle"]'::jsonb,0,'Urgent care is for minor issues. Anything life-threatening is a 911 call — never transport them yourself.','Las clínicas de urgencias son para cosas menores. Algo que pone en riesgo la vida es para el 911; nunca lo lleves tú.','https://www.redcross.org/take-a-class/cpr',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','health','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','food','At 2 a.m., a guest asks where they can sit down and eat nearby. What''s a verified 24-hour option?','A las 2 a. m., un huésped pregunta dónde puede sentarse a comer cerca. ¿Qué opción 24 horas está confirmada?','["IHOP on Killebrew Drive", "The hotel breakfast area", "The MOA food court", "Nine Mile Brewing"]'::jsonb,'["El IHOP de Killebrew Drive", "El área de desayuno del hotel", "El área de comida del MOA", "Nine Mile Brewing"]'::jsonb,0,'IHOP at 2231 Killebrew Dr. lists 24-hour service. Always suggest the guest check the app in case hours change.','El IHOP de 2231 Killebrew Dr. abre las 24 horas. Siempre sugiere revisar la app por si cambian el horario.','https://restaurants.ihop.com/en-us/mn/bloomington/breakfast-2231-killebrew-dr-5437/late-night-food',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','food','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','food','A guest wants a late-night drive-thru burger. Which nearby spot is listed as open 24 hours?','Un huésped quiere una hamburguesa de autoservicio en la madrugada. ¿Qué lugar cercano abre las 24 horas?','["The Walgreens inside MOA", "The MOA food court", "Nine Mile Brewing", "Wendy''s at 2001 W. American Blvd"]'::jsonb,'["El Walgreens dentro del MOA", "El área de comida del MOA", "Nine Mile Brewing", "El Wendy''s de 2001 W. American Blvd"]'::jsonb,3,'That Wendy''s lists 24-hour drive-thru. Hours can change, so suggest checking the app before heading out.','Ese Wendy''s tiene autoservicio 24 horas. El horario puede cambiar, así que sugiere revisar la app antes de salir.','https://locations.wendys.com/united-states/mn/bloomington/2001-american-blvd-w',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','food','A guest wants an all-day-breakfast diner open around the clock. Which one do you suggest?','Un huésped quiere un diner con desayuno todo el día, abierto a cualquier hora. ¿Cuál le sugieres?','["Target", "Denny''s on W. American Blvd", "The hotel bar", "SEA LIFE café"]'::jsonb,'["Target", "El Denny''s de W. American Blvd", "El bar del hotel", "La cafetería de SEA LIFE"]'::jsonb,1,'Denny''s at 4209 W. American Blvd lists 24-hour service with all-day breakfast.','El Denny''s de 4209 W. American Blvd abre las 24 horas y tiene desayuno todo el día.','https://locations.dennys.com/mn/bloomington/248080',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','shopping','A guest forgot a phone charger and asks for the nearest Target.','A un huésped se le olvidó el cargador y pregunta por el Target más cercano.','["Target Bloomington 79th and Penn (2555 W. 79th St.)", "There''s a Target inside Terminal 1", "There''s no Target in Bloomington", "Target Knollwood in St. Louis Park"]'::jsonb,'["El Target Bloomington 79th and Penn (2555 W. 79th St.)", "Hay un Target dentro de la Terminal 1", "No hay Target en Bloomington", "El Target Knollwood en St. Louis Park"]'::jsonb,0,'Target''s store locator lists Bloomington 79th and Penn at 2555 W. 79th St. MOA stores are closer for small items.','El buscador de Target muestra la tienda Bloomington 79th and Penn en 2555 W. 79th St. Para cosas pequeñas, las tiendas del MOA quedan más cerca.','https://www.target.com/sl/bloomington-79th-and-penn/5',array['front_desk','gm','night_audit']::text[],'role','med',array['local','shopping','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','liquor','At 9:30 p.m. on a Tuesday, a guest asks if they can still buy a bottle of wine at a liquor store. What do you say?','A las 9:30 p. m. de un martes, un huésped pregunta si todavía puede comprar una botella de vino en una licorería. ¿Qué le dices?','["Liquor stores can''t sell wine", "No, stores close at 8 p.m.", "Yes, until 2 a.m.", "Yes, but hurry — Minnesota liquor stores can sell until 10 p.m. Mon–Sat"]'::jsonb,'["Las licorerías no pueden vender vino", "No, cierran a las 8 p. m.", "Sí, hasta las 2 a. m.", "Sí, pero que se apure: en Minnesota las licorerías venden hasta las 10 p. m. de lunes a sábado"]'::jsonb,3,'State law allows off-sale 8 a.m.–10 p.m. Mon–Sat. Individual stores and cities may close earlier.','La ley estatal permite vender para llevar de 8 a. m. a 10 p. m. de lunes a sábado. Cada tienda o ciudad puede cerrar antes.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','liquor','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','liquor','A guest asks on Sunday afternoon whether liquor stores are open.','Un huésped pregunta el domingo en la tarde si las licorerías están abiertas.','["No, Sunday sales are banned in Minnesota", "Only in St. Paul", "Yes, they can open 11 a.m.–6 p.m. on Sunday", "Yes, until 10 p.m."]'::jsonb,'["No, en Minnesota no se vende los domingos", "Solo en St. Paul", "Sí, pueden abrir de 11 a. m. a 6 p. m. el domingo", "Sí, hasta las 10 p. m."]'::jsonb,2,'Minnesota allows Sunday off-sale 11 a.m.–6 p.m. Stores choose whether to open.','Minnesota permite vender para llevar el domingo de 11 a. m. a 6 p. m. Cada tienda decide si abre.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','liquor','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','liquor','On Christmas Eve at 8:30 p.m. a guest wants to buy champagne at a liquor store. What''s the rule?','En Nochebuena a las 8:30 p. m. un huésped quiere comprar champán en una licorería. ¿Cuál es la regla?','["Off-sale ends at 8 p.m. on Christmas Eve, so they''re too late", "Stores stay open until midnight", "It''s like any other night, until 10 p.m.", "Only grocery stores can sell it"]'::jsonb,'["En Nochebuena la venta para llevar termina a las 8 p. m., ya es tarde", "Las tiendas abren hasta medianoche", "Es como cualquier noche, hasta las 10 p. m.", "Solo los supermercados pueden venderlo"]'::jsonb,0,'Minnesota bans off-sale after 8 p.m. on Christmas Eve, and all day on Thanksgiving and Christmas.','En Minnesota no se vende para llevar después de las 8 p. m. en Nochebuena, ni en todo el día de Acción de Gracias o Navidad.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['bartender','front_desk','gm','night_audit']::text[],'role','hard',array['local','liquor','mspms']::text[],'MSPMS','12-15','12-26','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','liquor','A guest wants to buy beer at a liquor store on Thanksgiving. What do you tell them?','Un huésped quiere comprar cerveza en una licorería el Día de Acción de Gracias. ¿Qué le dices?','["Open only until noon", "Liquor stores can''t sell on Thanksgiving — buy the day before", "Open normal hours", "Only at the airport"]'::jsonb,'["Abren solo hasta el mediodía", "Las licorerías no pueden vender en Acción de Gracias; que compre un día antes", "Abren en horario normal", "Solo en el aeropuerto"]'::jsonb,1,'State law prohibits off-sale on Thanksgiving Day.','La ley estatal prohíbe la venta para llevar el Día de Acción de Gracias.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','liquor','mspms']::text[],'MSPMS','11-15','11-28','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','winter','It snowed overnight and Bloomington declared a snow emergency. A guest parked on the street. What do you tell them?','Nevó en la noche y Bloomington declaró emergencia por nieve. Un huésped se estacionó en la calle. ¿Qué le dices?','["Leave it, plows go around cars", "It''s fine, the ban is only downtown", "Only trucks need to move", "Move it into the hotel lot — city streets must be clear until plowed or the car can be towed"]'::jsonb,'["Que lo deje, los quitanieves le dan la vuelta", "No pasa nada, la prohibición es solo en el centro", "Solo deben moverse las camionetas", "Que lo mueva al estacionamiento del hotel; las calles deben quedar libres hasta que pase el quitanieves o se lo pueden llevar"]'::jsonb,3,'In a Bloomington snow emergency, vehicles must be off city streets until plowed full width (up to 48 hours) or they may be towed.','Durante una emergencia por nieve en Bloomington, los carros deben salir de las calles hasta que se limpien por completo (hasta 48 horas) o los pueden remolcar.','https://www.bloomingtonmn.gov/mnt/snow-removal-and-snow-emergency-information',array['front_desk','gm','night_audit']::text[],'role','med',array['local','winter','mspms']::text[],'MSPMS','11-01','04-15','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','winter','A guest from Texas asks how early to leave for a 7 a.m. flight during a snowstorm. Best advice?','Un huésped de Texas pregunta con cuánto tiempo salir para un vuelo de las 7 a. m. durante una tormenta de nieve. ¿El mejor consejo?','["Same as a sunny day", "Leave 15 minutes before boarding", "Wait until the snow stops", "Leave earlier than usual and check the flight status — roads and security can be slow"]'::jsonb,'["Igual que un día soleado", "Salir 15 minutos antes de abordar", "Esperar a que deje de nevar", "Salir antes de lo normal y revisar el estado del vuelo; las calles y la seguridad pueden ir lentas"]'::jsonb,3,'Snow slows roads, de-icing delays flights and lines build. Add buffer time and confirm with the airline.','La nieve hace más lentas las calles, el deshielo retrasa los vuelos y se hacen filas. Hay que dejar tiempo extra y confirmar con la aerolínea.','https://www.mspairport.com/airport/terminal-information',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','winter','mspms']::text[],'MSPMS','11-01','04-15','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest landed and wants Uber instead of the shuttle at Terminal 1. Where''s pickup?','Un huésped aterrizó en la Terminal 1 y prefiere Uber en vez del shuttle. ¿Dónde lo recogen?','["Gold Ramp Level 1 shuttle stop", "Follow Ground Transportation signs to the rideshare zone on Level 1 of the Ground Transportation Center", "Any door outside baggage claim", "Upper departures curb"]'::jsonb,'["La parada de shuttles del Gold Ramp, nivel 1", "Seguir los letreros de Ground Transportation a la zona de rideshare en el nivel 1 del Ground Transportation Center", "Cualquier puerta afuera del área de equipaje", "La acera de salidas"]'::jsonb,1,'At Terminal 1 rideshare pickups are in the Ground Transportation Center, Level 1 (Zones A–C).','En la Terminal 1 el rideshare recoge en el Ground Transportation Center, nivel 1 (zonas A a C).','https://www.mspairport.com/directions/ground-transportation/app-based-ride-services',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest at Terminal 2 can''t find their Lyft. Where should they go?','Un huésped en la Terminal 2 no encuentra su Lyft. ¿A dónde debe ir?','["Skyway level of the Ground Transportation Center", "The departures curb", "Gold Ramp Level 1", "The old Purple Ramp curb"]'::jsonb,'["Al nivel skyway del Ground Transportation Center", "A la acera de salidas", "Al nivel 1 del Gold Ramp", "A la acera vieja del Purple Ramp"]'::jsonb,0,'Terminal 2 rideshare pickup moved to the skyway level of the Ground Transportation Center. The old location no longer applies.','En la Terminal 2 el rideshare se cambió al nivel skyway del Ground Transportation Center. La ubicación anterior ya no aplica.','https://www.mspairport.com/directions/ground-transportation/app-based-ride-services',array['driver','front_desk','gm','night_audit']::text[],'role','hard',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','shuttle','A guest calls from the airport for the shuttle. What number should they have called?','Un huésped llama desde el aeropuerto pidiendo el shuttle. ¿A qué número debía llamar?','["911", "The airport main line", "Metro Transit", "The hotel''s front desk, 952-854-0300"]'::jsonb,'["Al 911", "A la línea principal del aeropuerto", "A Metro Transit", "A la recepción del hotel, 952-854-0300"]'::jsonb,3,'Guests call the hotel at 952-854-0300 after collecting bags; the shuttle meets them at Gold Ramp Level 1.','El huésped llama al hotel al 952-854-0300 cuando ya tenga sus maletas; el shuttle lo recoge en el Gold Ramp, nivel 1.','https://www.mspairport.com/directions/ground-transportation/hotel-shuttles',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['local','shuttle','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','shuttle','A guest asks if the shuttle costs anything to MSP or MOA.','Un huésped pregunta si el shuttle al MSP o al MOA cuesta algo.','["No, it''s complimentary", "Free only for Gold members", "$10 each way", "Only the airport is free"]'::jsonb,'["No, es gratis", "Gratis solo para socios Gold", "$10 por trayecto", "Solo el del aeropuerto es gratis"]'::jsonb,0,'SpringHill Suites MSP Airport/Mall of America lists a complimentary shuttle to both the airport and Mall of America.','SpringHill Suites MSP Airport/Mall of America ofrece shuttle gratuito al aeropuerto y al Mall of America.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','shuttle','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','shuttle','A guest wants the shuttle to drop them at a restaurant downtown Minneapolis. What do you say?','Un huésped quiere que el shuttle lo deje en un restaurante del centro de Minneapolis. ¿Qué le dices?','["Explain the shuttle serves MSP and MOA, and offer the Blue Line or a rideshare", "Charge them cash", "Take them since it''s slow", "Say downtown is unsafe"]'::jsonb,'["Explicarle que el shuttle va al MSP y al MOA, y ofrecerle la Blue Line o un rideshare", "Cobrarle en efectivo", "Llevarlo porque está tranquilo", "Decirle que el centro es peligroso"]'::jsonb,0,'The hotel lists shuttle service to the airport and MOA. Offer friendly alternatives instead of going off-route.','El hotel ofrece shuttle al aeropuerto y al MOA. Ofrece alternativas amables en vez de salirte de la ruta.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['local','shuttle','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','parking','A guest asks about parking at the hotel.','Un huésped pregunta por el estacionamiento del hotel.','["Send them to the MOA ramp", "Say there''s no parking", "Give the current posted rate and in/out rules from the desk — rates change", "Tell them it''s always free"]'::jsonb,'["Mandarlo a la rampa del MOA", "Decirle que no hay estacionamiento", "Darle la tarifa vigente y las reglas de entrada y salida que tiene la recepción; las tarifas cambian", "Decirle que siempre es gratis"]'::jsonb,2,'Parking rates are set by the hotel and change. Quote what''s posted in the system today.','Las tarifas de estacionamiento las fija el hotel y cambian. Da la que aparece hoy en el sistema.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','parking','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest asks what''s the address of the hotel for their Uber.','Un huésped pregunta la dirección del hotel para su Uber.','["2870 Metro Drive, Bloomington, MN 55425", "6051 Golden Hills Drive", "4300 Glumack Drive", "60 E. Broadway, Bloomington"]'::jsonb,'["2870 Metro Drive, Bloomington, MN 55425", "6051 Golden Hills Drive", "4300 Glumack Drive", "60 E. Broadway, Bloomington"]'::jsonb,0,'Know your address cold — guests, drivers and 911 all need it.','Apréndete la dirección de memoria: los huéspedes, los choferes y el 911 la necesitan.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest''s rideshare driver is confused because there are two hotels side by side on Metro Drive. What do you tell the guest?','El chofer de rideshare de un huésped está confundido porque hay dos hoteles juntos en Metro Drive. ¿Qué le dices al huésped?','["Say any door is fine", "Tell them to meet at MOA", "Just say Metro Drive", "Give the exact number 2870 Metro Drive and the hotel name"]'::jsonb,'["Decir que cualquier puerta sirve", "Decirle que se vean en el MOA", "Solo decir Metro Drive", "Darle el número exacto, 2870 Metro Drive, y el nombre del hotel"]'::jsonb,3,'Hampton (2860) and SpringHill (2870) are neighbors on Metro Drive. The exact number avoids mix-ups.','El Hampton (2860) y el SpringHill (2870) están juntos en Metro Drive. El número exacto evita confusiones.','https://www.mspairport.com/directions/ground-transportation/hotel-shuttles',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','local','A guest asks where the Minnesota Zoo is relative to the hotel.','Un huésped pregunta dónde queda el Minnesota Zoo en relación al hotel.','["About 7 miles away, in Apple Valley — best by car or rideshare", "Next to Target Field", "Across the street", "Inside Mall of America"]'::jsonb,'["A unas 7 millas, en Apple Valley; mejor en carro o rideshare", "Junto a Target Field", "Cruzando la calle", "Dentro del Mall of America"]'::jsonb,0,'Hilton lists the Minnesota Zoo at about 7 miles.','Hilton indica que el Minnesota Zoo está a unas 7 millas.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/hotel-location/',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','local','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','transit','Between 11 p.m. and 4:30 a.m., how do travelers get between MSP terminals?','Entre las 11 p. m. y las 4:30 a. m., ¿cómo se mueven los viajeros entre las terminales del MSP?','["There''s no way until morning", "Trains still run between the terminals overnight (with a Blue Line airport shuttle option late at night)", "Walk outside along the highway", "Only taxis"]'::jsonb,'["No hay forma hasta la mañana", "Los trenes siguen entre terminales en la madrugada (y hay un shuttle de la Blue Line en ciertas horas)", "Caminar por la orilla de la carretera", "Solo en taxi"]'::jsonb,1,'Terminal-to-terminal service runs 24 hours; MSP notes a Blue Line airport shuttle option 11 p.m.–4:30 a.m.','El servicio entre terminales funciona las 24 horas; el MSP menciona un shuttle de la Blue Line de 11 p. m. a 4:30 a. m.','https://www.mspairport.com/flights-and-airlines',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','airport','A guest wants to return a rental car at MSP. Which terminal?','Un huésped quiere devolver un carro rentado en el MSP. ¿En qué terminal?','["At the Mall of America", "Either — on-airport rental companies have counters at both", "Only Terminal 1", "Only Terminal 2"]'::jsonb,'["En el Mall of America", "En cualquiera; las rentadoras del aeropuerto tienen mostrador en las dos", "Solo en la Terminal 1", "Solo en la Terminal 2"]'::jsonb,1,'MSP says rental cars can be returned at either terminal.','El MSP indica que los carros rentados se pueden devolver en cualquier terminal.','https://www.mspairport.com/directions/ground-transportation/car-rentals',array['front_desk','gm','night_audit']::text[],'role','med',array['local','airport','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','bar','A guest at the bar asks the latest you can legally serve them tonight in Minnesota.','Un huésped en el bar pregunta hasta qué hora le pueden servir legalmente hoy en Minnesota.','["4 a.m.", "There''s no limit", "Midnight statewide", "Bars can serve until 2 a.m. with a state permit; our bar follows its own posted hours"]'::jsonb,'["Hasta las 4 a. m.", "No hay límite", "Hasta medianoche en todo el estado", "Los bares pueden servir hasta las 2 a. m. con permiso estatal; nuestro bar sigue su horario publicado"]'::jsonb,3,'Minnesota law allows on-sale until 2 a.m. (1–2 a.m. needs a permit). Our bar''s posted hours come first.','La ley de Minnesota permite servir hasta las 2 a. m. (de 1 a 2 a. m. requiere permiso). Primero aplica el horario de nuestro bar.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','bar','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','bar','A guest at the bar wants to watch the Vikings game in person. How do they get to the stadium?','Un huésped en el bar quiere ver el partido de los Vikings en persona. ¿Cómo llega al estadio?','["Route 54", "Blue Line north to U.S. Bank Stadium station", "Red Line", "Shuttle to MOA, then walk"]'::jsonb,'["La ruta 54", "La Blue Line hacia el norte hasta la estación U.S. Bank Stadium", "La Red Line", "El shuttle al MOA y luego caminar"]'::jsonb,1,'U.S. Bank Stadium has its own Blue Line station — no game-day parking stress.','U.S. Bank Stadium tiene su propia estación de la Blue Line, así se evita el estrés de estacionarse.','https://www.minneapolis.org/map-transportation/major-event-parking-transit/',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['local','bar','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','bar','A guest asks for a local brewery taproom in Bloomington.','Un huésped pide una cervecería local con taproom en Bloomington.','["Target Center", "Under Pressure in Golden Valley", "Nine Mile Brewing on James Ave S", "The MOA Walgreens"]'::jsonb,'["Target Center", "Under Pressure en Golden Valley", "Nine Mile Brewing en James Ave S", "El Walgreens del MOA"]'::jsonb,2,'Nine Mile Brewing is at 9555 James Ave S, Bloomington. Suggest a rideshare — never drive after drinking.','Nine Mile Brewing está en 9555 James Ave S, Bloomington. Sugiere un rideshare; nunca manejar después de tomar.','https://exa.ai/library/places?q=3cfaedfa7049d53a',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','bar','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','bar','A guest who''s been drinking asks how to get to a bar downtown. Best answer?','Un huésped que ha estado tomando pregunta cómo llegar a un bar del centro. ¿La mejor respuesta?','["Lend them a parking pass", "Suggest a rideshare or the Blue Line — not driving", "Tell them the fastest highway", "Offer the hotel shuttle downtown"]'::jsonb,'["Prestarle un pase de estacionamiento", "Sugerirle un rideshare o la Blue Line, que no maneje", "Decirle la autopista más rápida", "Ofrecerle el shuttle del hotel al centro"]'::jsonb,1,'Guest safety and liquor liability come first: point them to rides that don''t involve them driving.','La seguridad del huésped y la responsabilidad por el alcohol van primero: ofrece opciones donde no tenga que manejar.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','bar','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','bar','Twins fans at the bar ask how to get to tomorrow''s game.','Unos fans de los Twins en el bar preguntan cómo llegar al partido de mañana.','["Route 54 to St. Paul", "Shuttle to MOA", "Green Line to Grand Casino Arena", "Blue Line to the Target Field station, the end of the line"]'::jsonb,'["La ruta 54 a St. Paul", "El shuttle al MOA", "La Green Line al Grand Casino Arena", "La Blue Line hasta la estación Target Field, la última"]'::jsonb,3,'Target Field station is the north end of the Blue Line.','La estación Target Field es el extremo norte de la Blue Line.','https://www.metrotransit.org/stadiums/target-field/',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['local','bar','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','local','A guest asks what the hotel''s address is for their GPS.','Un huésped pregunta la dirección del hotel para su GPS.','["6051 Golden Hills Drive, Golden Valley, MN 55416", "60 E. Broadway", "2860 Metro Drive, Bloomington", "1621 West End Blvd"]'::jsonb,'["6051 Golden Hills Drive, Golden Valley, MN 55416", "60 E. Broadway", "2860 Metro Drive, Bloomington", "1621 West End Blvd"]'::jsonb,0,'Know the address by heart — for guests, rides and 911.','Apréndete la dirección de memoria: para huéspedes, choferes y el 911.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail/directions',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','local','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','shuttle','A guest calls from MSP asking for the hotel shuttle. What do you tell them?','Un huésped llama desde el MSP pidiendo el shuttle del hotel. ¿Qué le dices?','["Take the shuttle to MOA first", "Call back in an hour", "Meet at Gold Ramp Level 1", "We don''t have an airport shuttle — suggest a taxi or rideshare"]'::jsonb,'["Que tome primero el shuttle al MOA", "Que vuelva a llamar en una hora", "Que nos vea en el Gold Ramp, nivel 1", "No tenemos shuttle al aeropuerto; sugiérele taxi o rideshare"]'::jsonb,3,'IHG lists no airport or local shuttle at this hotel. Give clear alternatives right away.','IHG indica que este hotel no tiene shuttle al aeropuerto ni local. Da alternativas claras de inmediato.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail/directions',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','shuttle','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','shopping','A guest wants restaurants and a movie within a few minutes. Where do you point them?','Un huésped quiere restaurantes y una película a pocos minutos. ¿A dónde lo mandas?','["The airport", "Mall of America", "The Shops at West End in St. Louis Park", "Target Field"]'::jsonb,'["Al aeropuerto", "Al Mall of America", "A The Shops at West End, en St. Louis Park", "A Target Field"]'::jsonb,2,'West End (1621 West End Blvd) has restaurants and a Marcus theater, right off I-394 and Hwy 100.','West End (1621 West End Blvd) tiene restaurantes y un cine Marcus, junto a la I-394 y la Hwy 100.','https://theshopsatwestend.com/',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','shopping','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','A group wants a big sit-down restaurant at West End. Which is there?','Un grupo quiere un restaurante grande para sentarse en West End. ¿Cuál está ahí?','["Nine Mile Brewing", "Denny''s on American Blvd", "IHOP on Killebrew Drive", "Yard House"]'::jsonb,'["Nine Mile Brewing", "El Denny''s de American Blvd", "El IHOP de Killebrew Drive", "Yard House"]'::jsonb,3,'West End''s dining directory lists Yard House, Punch Bowl Social, CRAVE, The Local and more.','El directorio de West End incluye Yard House, Punch Bowl Social, CRAVE, The Local y otros.','https://theshopsatwestend.com/directory/dining',array['front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','food','A guest wants games and food together nearby. Which West End spot fits?','Un huésped quiere juegos y comida en el mismo lugar, cerca. ¿Qué lugar de West End le queda?','["Park Nicollet Urgent Care", "Walgreens", "The Urgency Room", "Punch Bowl Social"]'::jsonb,'["Park Nicollet Urgent Care", "Walgreens", "The Urgency Room", "Punch Bowl Social"]'::jsonb,3,'Punch Bowl Social at West End combines dining and games.','Punch Bowl Social, en West End, combina comida y juegos.','https://theshopsatwestend.com/directory/dining',array['front_desk','gm','night_audit']::text[],'role','med',array['local','food','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','health','A guest twisted an ankle and wants walk-in urgent care tonight. What''s closest?','Un huésped se torció el tobillo y quiere una clínica de urgencias sin cita hoy en la noche. ¿Cuál queda más cerca?','["Hennepin County Library", "The airport", "Mall of America clinic", "The Urgency Room, 6110 Golden Hills Dr — on our street"]'::jsonb,'["La biblioteca del condado", "El aeropuerto", "La clínica del Mall of America", "The Urgency Room, en 6110 Golden Hills Dr, en nuestra misma calle"]'::jsonb,3,'The Urgency Room at 6110 Golden Hills Dr. lists daily 8 a.m.–9 p.m. walk-ins. For emergencies, call 911.','The Urgency Room, en 6110 Golden Hills Dr., atiende sin cita todos los días de 8 a. m. a 9 p. m. En emergencias, llama al 911.','https://www.urgencyroom.com/locations/golden-valley/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','health','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','health','What hours does The Urgency Room near the hotel list?','¿Qué horario tiene The Urgency Room cerca del hotel?','["Weekdays only", "Daily 8 a.m.–9 p.m.", "Noon–midnight", "24 hours"]'::jsonb,'["Solo entre semana", "Todos los días de 8 a. m. a 9 p. m.", "Del mediodía a la medianoche", "Las 24 horas"]'::jsonb,1,'Its site lists 8 a.m.–9 p.m. every day. After hours, serious issues go to an ER or 911.','Su sitio indica de 8 a. m. a 9 p. m. todos los días. Fuera de ese horario, lo grave va a una sala de emergencias o al 911.','https://www.urgencyroom.com/locations/golden-valley/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','health','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','health','On a Saturday afternoon a guest prefers Park Nicollet urgent care. Until when is the St. Louis Park clinic open on weekends?','Un sábado en la tarde un huésped prefiere la clínica de urgencias Park Nicollet. ¿Hasta qué hora abre la de St. Louis Park el fin de semana?','["It''s closed weekends", "Midnight", "8 p.m.", "5 p.m."]'::jsonb,'["Cierra los fines de semana", "Hasta medianoche", "Hasta las 8 p. m.", "Hasta las 5 p. m."]'::jsonb,3,'Park Nicollet Urgent Care St. Louis Park (3850 Park Nicollet Blvd) lists weekends 8 a.m.–5 p.m. and weekdays 8 a.m.–8 p.m.','Park Nicollet Urgent Care St. Louis Park (3850 Park Nicollet Blvd) abre fines de semana de 8 a. m. a 5 p. m. y entre semana de 8 a. m. a 8 p. m.','https://www.healthpartners.com/care/find/location/urgent-care/park-nicollet/st-louis-park-3850/',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','health','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','health','A guest needs a pharmacy with a drive-thru in Golden Valley.','Un huésped necesita una farmacia con autoservicio en Golden Valley.','["The Urgency Room", "Target Field", "The MOA Walgreens", "Walgreens at 2500 Winnetka Ave N"]'::jsonb,'["The Urgency Room", "Target Field", "El Walgreens del MOA", "El Walgreens de 2500 Winnetka Ave N"]'::jsonb,3,'Walgreens lists a drive-thru pharmacy at 2500 Winnetka Ave N. Call to confirm pharmacy hours.','Walgreens tiene farmacia con autoservicio en 2500 Winnetka Ave N. Llama para confirmar el horario de la farmacia.','https://www.walgreens.com/storelocator/drive-thru-pharmacy/golden-valley-mn',array['front_desk','gm','night_audit']::text[],'role','med',array['local','health','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','shopping','A guest needs a Target nearby. Which one do you suggest?','Un huésped necesita un Target cerca. ¿Cuál le sugieres?','["Target Knollwood, 8900 Highway 7, St. Louis Park", "There''s one inside the hotel", "Target Field", "Target Bloomington 79th and Penn"]'::jsonb,'["El Target Knollwood, en 8900 Highway 7, St. Louis Park", "Hay uno dentro del hotel", "Target Field", "El Target Bloomington 79th and Penn"]'::jsonb,0,'Target''s store locator lists Knollwood at 8900 Highway 7.','El buscador de Target muestra la tienda Knollwood en 8900 Highway 7.','https://www.target.com/sl/knollwood-hwy-7/2189',array['front_desk','gm','night_audit']::text[],'role','easy',array['local','shopping','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','transit','A guest without a car asks which bus runs near the hotel.','Un huésped sin carro pregunta qué autobús pasa cerca del hotel.','["Metro Transit Route 9 (and limited-stop 645)", "The Red Line", "Route 54", "The Blue Line"]'::jsonb,'["La ruta 9 de Metro Transit (y la 645 de paradas limitadas)", "La Red Line", "La ruta 54", "La Blue Line"]'::jsonb,0,'Routes 9 and 645 stop near Golden Hills Dr. (Zarthan Ave & Wayzata Blvd area).','Las rutas 9 y 645 paran cerca de Golden Hills Dr. (por Zarthan Ave y Wayzata Blvd).','https://moovitapp.com/index/en/public_transit-Golden_Hills_Drive-MinneapolisSt_Paul_MN-street_2783882-1143',array['front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','transit','A guest wants a transit hub where several local buses meet near West End. Which one?','Un huésped busca una terminal donde se juntan varios autobuses cerca de West End. ¿Cuál?','["Mall of America Station", "Louisiana Avenue Transit Center", "Union Depot", "Target Field Station"]'::jsonb,'["La estación Mall of America", "Louisiana Avenue Transit Center", "Union Depot", "La estación Target Field"]'::jsonb,1,'Louisiana Avenue Transit Center in St. Louis Park serves Routes 9 and 645, among others.','El Louisiana Avenue Transit Center, en St. Louis Park, da servicio a las rutas 9 y 645, entre otras.','https://www.metrotransit.org/louisiana-avenue-transit-center',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','transit','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','transit','A guest wants to reach a Twins game without driving. What''s a reasonable plan?','Un huésped quiere ir a un partido de los Twins sin manejar. ¿Qué plan le das?','["Walk the whole way", "Rideshare (about 5 miles) or a bus toward downtown, then walk to Target Field", "Blue Line from the hotel", "Hotel shuttle"]'::jsonb,'["Caminar todo el camino", "Rideshare (unas 5 millas) o autobús hacia el centro y caminar a Target Field", "La Blue Line desde el hotel", "El shuttle del hotel"]'::jsonb,1,'There''s no light rail station or shuttle here. Downtown and Target Field are a short ride away.','Aquí no hay estación de tren ligero ni shuttle. El centro y Target Field están a un viaje corto.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail/directions',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','transit','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','local','A guest flying out asks the best way to MSP from Golden Valley.','Un huésped que vuela pregunta cuál es la mejor forma de llegar al MSP desde Golden Valley.','["The Mall of America shuttle", "Taxi or rideshare, leaving extra time — we have no airport shuttle", "Walk to the Blue Line", "The hotel shuttle"]'::jsonb,'["El shuttle del Mall of America", "Taxi o rideshare, con tiempo de sobra; no tenemos shuttle al aeropuerto", "Caminar a la Blue Line", "El shuttle del hotel"]'::jsonb,1,'IHG lists no airport shuttle. Confirm the guest''s terminal (T1 vs T2) before they book the ride.','IHG indica que no hay shuttle al aeropuerto. Confirma la terminal del huésped (T1 o T2) antes de que pida el viaje.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail/directions',array['front_desk','gm','night_audit']::text[],'role','med',array['local','local','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','parking','A guest with a large truck and trailer asks where to park.','Un huésped con una camioneta grande y remolque pregunta dónde estacionarse.','["On Golden Hills Drive overnight", "In the front fire lane", "The rear lot has oversized/truck parking", "At West End"]'::jsonb,'["En Golden Hills Drive toda la noche", "En el carril de bomberos del frente", "En el estacionamiento de atrás hay lugares para vehículos grandes", "En West End"]'::jsonb,2,'IHG notes oversized and truck parking in the rear lot.','IHG indica que hay estacionamiento para vehículos grandes en la parte de atrás.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail/directions',array['front_desk','gm','night_audit']::text[],'role','med',array['local','parking','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','parking','A guest with an electric car asks about charging.','Un huésped con carro eléctrico pregunta si puede cargarlo.','["No chargers anywhere nearby", "Plug into a room outlet through the window", "Only at the airport", "We have EV spots, including Tesla chargers"]'::jsonb,'["No hay cargadores cerca", "Que lo conecte a un enchufe del cuarto por la ventana", "Solo en el aeropuerto", "Tenemos lugares para carros eléctricos, incluyendo cargadores Tesla"]'::jsonb,3,'IHG lists 4 EV spaces: 3 Tesla and 1 general EV charger.','IHG indica 4 lugares para carros eléctricos: 3 Tesla y 1 cargador general.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail/directions',array['front_desk','gm','night_audit']::text[],'role','med',array['local','parking','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','liquor','At 9:45 p.m. on a Friday, a guest asks if they can grab a bottle at a liquor store.','A las 9:45 p. m. de un viernes, un huésped pregunta si todavía alcanza a comprar una botella.','["Yes, until 2 a.m.", "No, sales stop at 6 p.m. on Fridays", "Maybe — state law allows until 10 p.m., but many stores close earlier, so call first", "Only grocery stores sell liquor"]'::jsonb,'["Sí, hasta las 2 a. m.", "No, los viernes se deja de vender a las 6 p. m.", "Tal vez: la ley permite hasta las 10 p. m., pero muchas cierran antes; que llame primero", "Solo los supermercados venden licor"]'::jsonb,2,'Minnesota off-sale runs 8 a.m.–10 p.m. Mon–Sat at most; stores may close earlier.','En Minnesota la venta para llevar es de 8 a. m. a 10 p. m. de lunes a sábado como máximo; algunas tiendas cierran antes.','https://www.revisor.mn.gov/statutes/cite/340a.504',array['front_desk','gm','night_audit']::text[],'role','med',array['local','liquor','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','local','A guest asks for a local brewery near the hotel.','Un huésped pregunta por una cervecería local cerca del hotel.','["Target Center", "Under Pressure Brewing in Golden Valley", "U.S. Bank Stadium", "Nine Mile Brewing in Bloomington"]'::jsonb,'["Target Center", "Under Pressure Brewing en Golden Valley", "U.S. Bank Stadium", "Nine Mile Brewing en Bloomington"]'::jsonb,1,'Under Pressure Brewing & Blendery is at 8806 7th Ave N, Golden Valley. Suggest a ride, not driving after drinking.','Under Pressure Brewing & Blendery está en 8806 7th Ave N, Golden Valley. Sugiere que no maneje después de tomar.','https://www.underpressurebrewing.com/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','local','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','local','Another guest wants a brewery in St. Louis Park with a patio.','Otro huésped quiere una cervecería en St. Louis Park con patio.','["Yard House", "Steel Toe Brewing on W. 35th St.", "Under Pressure", "Nine Mile Brewing"]'::jsonb,'["Yard House", "Steel Toe Brewing en W. 35th St.", "Under Pressure", "Nine Mile Brewing"]'::jsonb,1,'Steel Toe Brewing is at 4848 W. 35th St., St. Louis Park, with a patio.','Steel Toe Brewing está en 4848 W. 35th St., St. Louis Park, y tiene patio.','https://www.steeltoebrewing.com/',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','local','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','winter','Minneapolis declared a snow emergency. A guest plans to park on a Minneapolis street the first night. When does the Day 1 ban start?','Minneapolis declaró emergencia por nieve. Un huésped piensa estacionarse en una calle de Minneapolis la primera noche. ¿Cuándo empieza la prohibición del Día 1?','["9 p.m. on snow emergency routes", "There''s no ban the first day", "Noon", "8 a.m. on every street"]'::jsonb,'["A las 9 p. m. en las rutas de emergencia por nieve", "No hay prohibición el primer día", "Al mediodía", "A las 8 a. m. en todas las calles"]'::jsonb,0,'Day 1 starts at 9 p.m. on snow emergency routes; Days 2 and 3 start at 8 a.m. on other streets.','El Día 1 empieza a las 9 p. m. en las rutas de emergencia; los Días 2 y 3 empiezan a las 8 a. m. en las demás calles.','https://www.minneapolismn.gov/getting-around/snow/snow-emergencies/snow-parking-rules/',array['front_desk','gm','night_audit']::text[],'role','hard',array['local','winter','mspwe']::text[],'MSPWE','11-01','04-15','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','winter','A guest''s car is parked in our lot during a Minneapolis snow emergency. Do they need to move it?','El carro de un huésped está en nuestro estacionamiento durante una emergencia por nieve en Minneapolis. ¿Tiene que moverlo?','["Only if it''s white", "No — snow emergency rules are for city streets; follow our lot''s plowing notice", "Yes, to the street", "Yes, all cars statewide must move"]'::jsonb,'["Solo si es blanco", "No, las reglas son para calles de la ciudad; que siga el aviso de limpieza de nuestro estacionamiento", "Sí, a la calle", "Sí, todos los carros del estado deben moverse"]'::jsonb,1,'City snow emergencies apply to public streets. Private lots follow the property''s own plowing plan.','Las emergencias por nieve de la ciudad aplican a las calles públicas. Los estacionamientos privados siguen el plan del hotel.','https://www.minneapolismn.gov/getting-around/snow/snow-emergencies/snow-parking-rules/',array['front_desk','gm','night_audit']::text[],'role','med',array['local','winter','mspwe']::text[],'MSPWE','11-01','04-15','2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','transit','Golden Valley guests want the Blue Line. What''s the catch?','Unos huéspedes en Golden Valley quieren tomar la Blue Line. ¿Cuál es el detalle?','["The Blue Line ends at West End", "The nearest Blue Line stations are downtown — get there by bus or rideshare first", "It only runs on weekends", "There''s a station across the street"]'::jsonb,'["La Blue Line termina en West End", "Las estaciones más cercanas están en el centro; primero hay que llegar en autobús o rideshare", "Solo funciona los fines de semana", "Hay una estación cruzando la calle"]'::jsonb,1,'The Blue Line runs from Target Field south to MOA. It doesn''t serve Golden Valley.','La Blue Line va de Target Field hacia el sur hasta el MOA. No pasa por Golden Valley.','https://www.metrotransit.org/Schedules/RouteMaps/jun26/blue',array['front_desk','gm','night_audit']::text[],'role','med',array['local','transit','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
